function Test-AiHistoryIdentity([hashtable]$Facts) {
 $exact=@{Root='C:/GUARANTEED OUTCOME/MOOLSOCIAL-WORKTREE-CODEX-ai-history-20261028';Branch='work/codex-backend/ai-history-20261028';Lane='codex_backend';Role='primary';WorkId='ai-history-20261028';Ticket='AI-HISTORY-01'}
 foreach($key in $exact.Keys){if(!$Facts.ContainsKey($key) -or $Facts[$key] -isnot [string] -or $Facts[$key] -cne $exact[$key]){return $false}}
 if(!$Facts.ContainsKey('Phase') -or $Facts.Phase -cnotin @('coordination_bootstrap','pre_commit','task_start','implementation')){return $false}
 $expected=if($Facts.Phase -ceq 'coordination_bootstrap'){'/root'}else{'/root/codex_backend_ai_history'}
 return $Facts.ContainsKey('Task') -and $Facts.Task -is [string] -and $Facts.Task -ceq $expected
}
