function Get-AiHistoryMetadataOwners { @('.gitattributes','config/codex-subagent-coordination-policy.json','config/cross-agent-incremental-ticket-gate.json','docs/quality/AI-HISTORY-BACKEND-20261028.json','docs/quality/AI-HISTORY-ACCEPTANCE-20261028.json','docs/quality/AI-HISTORY-CONTRACT-20261028.md','scripts/check-codex-subagent-coordination-policy.ps1','scripts/ai-history-admission.ps1','scripts/test-ai-history-admission.ps1') }
function Assert-AiHistoryOwners([string[]]$Actual,[string[]]$Allowed){foreach($owner in $Actual){Assert-Coordination ($owner -cin $Allowed) "Combined goal unadmitted owner: $owner"}}
function Invoke-AiHistoryAdmission {
 $base='9499d740a5171d892702387ceb1e5f6a413a336a';$contract='docs/quality/AI-HISTORY-CONTRACT-20261028.md';$hash='39CDABA8770338E6D370C92445A77D8702E0FAABDACEBA9EA51536EC25963965';$recordOwner='docs/quality/AI-HISTORY-BACKEND-20261028.json'
 $runtime=@(Get-AiHistoryRuntimeOwners);$metadata=@(Get-AiHistoryMetadataOwners);$owners=$runtime+$metadata
 $branch=@(Get-OctoberCompatibilityGitLines @('branch','--show-current'))[0]
 Assert-Coordination (Test-AiHistoryIdentity @{Root=$root.Replace('\','/');Branch=$branch;Lane=$ProductionLane;Role=$AgentRole;Task=$AgentTask;WorkId=$ProductionWorkId;Ticket=$ProductionTicketId;Phase=$ProductionPhase}) 'Combined exact identity/phase required.'
 Assert-Coordination ((Get-Sha256 (Join-Path $root $contract)) -ceq $hash) 'Accepted combined contract changed.'
 $record=Get-Content -Raw (Join-Path $root $recordOwner)|ConvertFrom-Json;$binding=$record.backendAdmission.binding
 Assert-Coordination ($binding.baselineHead -ceq $base -and $binding.branch -ceq $branch -and $binding.task -ceq '/root/codex_backend_ai_history' -and $binding.worktreePath -ceq 'C:/GUARANTEED OUTCOME/MOOLSOCIAL-WORKTREE-CODEX-ai-history-20261028' -and $binding.bootstrapCommitSubject -ceq 'coordination(ai-history-20261028): record exact bounded History admission' -and (@($binding.bootstrapOwners|Sort-Object)-join '|') -ceq (@($metadata|Sort-Object)-join '|') -and (@($record.backendAdmission.runtimeOwners|Sort-Object)-join '|') -ceq (@($runtime|Sort-Object)-join '|')) 'Exact combined owner binding changed.'
 $approval=Get-Content -Raw (Join-Path $root 'docs/quality/AI-HISTORY-ACCEPTANCE-20261028.json')|ConvertFrom-Json
 Assert-Coordination ($approval.acceptedUiCommit -ceq $base -and $approval.uiContractSha256 -ceq $hash -and $approval.founderAnswer -ceq 'THEN CONTINUE NEXT - GO AHEAD WITH NEXT SCOPE WHETHER BASELINE SEAL IF NEEDED OTHERWISE FIND NEXT TWO OR 3 SCOPE OR TICKETS TO CONTINUE WITH ONE BOUNDED GOAL AND USE STANDING AUTHORISATION OR APPROVAL WITHOUT STOP UNTILL NEW GOAL IS OPPO TESTED' -and $approval.localMetadataCommits -eq 1 -and !$approval.sourceFeatureCommits -and !$approval.backendBranchPush -and !$approval.deployment -and !$approval.productionAcceptance) 'Exact acceptance/authority differs.'
 $expected=(@(Get-OctoberCompatibilityGitLines @('show',"${base}:config/codex-subagent-coordination-policy.json"))-join "`n")|ConvertFrom-Json
 foreach($claim in @($expected.activeClaims)){$claim.owners=@($claim.owners|Where-Object {$_ -cnotin $owners})}
 $expected.activeClaims=@($expected.activeClaims)+@([pscustomobject]@{task='/root/codex_backend_ai_history';role='primary';owners=$owners})
 $expected.productionGitDiscipline.continuationBindings=@($expected.productionGitDiscipline.continuationBindings)+@($binding)
 $policy=Get-Content -Raw (Join-Path $root 'config/codex-subagent-coordination-policy.json')|ConvertFrom-Json
 Assert-Coordination (($policy|ConvertTo-Json -Depth 100 -Compress) -ceq ($expected|ConvertTo-Json -Depth 100 -Compress)) 'Unrelated policy changed.'
 $inc=(@(Get-OctoberCompatibilityGitLines @('show',"${base}:config/cross-agent-incremental-ticket-gate.json"))-join "`n")|ConvertFrom-Json
 $inc.uiFounderReview.acceptedScopes=@($inc.uiFounderReview.acceptedScopes)+@([pscustomobject]@{id='assistant.history';uiCommit=$base;contractPath=$contract;contractSha256=$hash})
 $actual=Get-Content -Raw (Join-Path $root 'config/cross-agent-incremental-ticket-gate.json')|ConvertFrom-Json
 Assert-Coordination (($actual|ConvertTo-Json -Depth 100 -Compress) -ceq ($inc|ConvertTo-Json -Depth 100 -Compress)) 'Unrelated incremental gate changed.'
 Assert-Coordination ($ExpectedRegistryEntryCount -eq 4624 -and $ExpectedRegistrySha256 -ceq '333A27362EB36CF334397E70EF58745494286D4EFA93A5AEC21C93AF28922C11' -and (Get-Sha256 (Join-Path $root 'config/codex-development-regression-registry.json')) -ceq $ExpectedRegistrySha256) 'Regression pin changed.'
 $head=@(Get-OctoberCompatibilityGitLines @('rev-parse','HEAD'))[0];Get-OctoberCompatibilityGitLines @('merge-base','--is-ancestor',$base,$head)|Out-Null
 $commits=@(Get-OctoberCompatibilityGitLines @('rev-list',"$base..$head"))
 Assert-Coordination ($commits.Count -le 1 -and @(Get-OctoberCompatibilityGitLines @('rev-list','--merges',"$base..$head")).Count -eq 0 -and @(Get-OctoberCompatibilityGitLines @('for-each-ref','--format=%(refname)','refs/replace')).Count -eq 0 -and @(Get-OctoberCompatibilityGitLines @('ls-files','-v')|Where-Object {$_ -cmatch '^[a-zS] '}).Count -eq 0) 'Only one metadata checkpoint; no history/index overrides.'
 $changed=@(@(Get-OctoberCompatibilityGitLines @('diff','--name-only',$base))+@(Get-OctoberCompatibilityGitLines @('ls-files','--others','--exclude-standard')))|Sort-Object -Unique
 Assert-AiHistoryOwners $changed $owners
 if($head -ceq $base){Assert-Coordination ($ProductionPhase -cin @('coordination_bootstrap','pre_commit')) 'Recorded clean admission required.';Assert-AiHistoryOwners $changed $metadata}
 else {Assert-Coordination ((@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%P',$head))[0]) -ceq $base -and (@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',$head))[0]) -ceq 'coordination(ai-history-20261028): record exact bounded History admission' -and (@(Get-OctoberCompatibilityGitLines @('diff','--name-only',$base,$head)|Sort-Object)-join '|') -ceq (@($metadata|Sort-Object)-join '|')) 'Metadata parent/subject/owners differ.';foreach($owner in $metadata){Get-OctoberCompatibilityGitLines @('diff','--exit-code',$head,'--',$owner)|Out-Null}}
 if($ProductionPhase -ceq 'pre_commit'){Assert-Coordination ($head -ceq $base -and (@(Get-OctoberCompatibilityGitLines @('diff','--cached','--name-only')|Sort-Object)-join '|') -ceq (@($metadata|Sort-Object)-join '|')) 'Only exact metadata commit authorised.'}
 if($ProductionPhase -cin @('coordination_bootstrap','task_start')){$remote=@(Get-OctoberCompatibilityGitLines @('ls-remote','--heads','origin','refs/heads/work/codex-backend/thin-b07-b04-20261027'));Assert-Coordination ($remote.Count -eq 1 -and ($remote[0] -split '\s+')[0] -ceq $base) 'Origin-exact sealed baseline required.'}
 if($ProductionPhase -ceq 'task_start'){Assert-Coordination (@(Get-OctoberCompatibilityGitLines @('status','--porcelain')).Count -eq 0) 'Task start not clean.'}
 & (Join-Path $root 'scripts/check-mvp-scope-gate-state.ps1') -RepositoryRoot $root -StatePath $recordOwner -CandidateId AI-HISTORY-01 -RequireExecutionAuthorized
 & (Join-Path $root 'scripts/check-cross-agent-incremental-ticket-gate.ps1') -RepositoryRoot $root -Phase implementation -Lane codex_backend -TicketId AI-HISTORY-01 -UiScope assistant.history -CandidateVersionName '1.0.0-r67.12' -CandidateVersionCode 2026102801 -PackageId com.moolsocial.app.runtime -AcceptedUiCommit $base -UiContractPath $contract -UiContractSha256 $hash
 Assert-ProductionSecretSafe -BaseCommit $base -HeadCommit $head
 Assert-ProductionSecretSafe -BaseCommit $base -HeadCommit $head -IndexOnly
 Write-Output 'AI History admission passed; 21 runtime/test owners; no source feature commit/push, cloud or APK authority.'
}
